-- v992: контент курса «Адаптация» — День 6 · Скрипты и демо. Сгенерировано gen-academy-adaptation.mjs

INSERT INTO academy_modules (id, course_id, sort, title, intro, gate, active) VALUES
 ($sd$a0000000-0000-0000-0002-000000000006$sd$, $sd$c0000000-0000-0000-0000-000000000002$sd$, 70, $sd$День 6 · Скрипты и демо$sd$, $sd$Самый плотный день: квалификация, холодный и входящий звонок, закрытие на демо и на продукт, стандарт демо-встречи, доверие и запись встреч.$sd$, $sd${"title":"Зачёт дня 6","tasks":["Ролёвка 1: проводишь квалификацию — 16 вопросов, оцениваешь лид (горячий / тёплый / холодный)","Ролёвка 2: закрываешь наставника (как руководителя) на демо по 5 блокам скрипта","Ролёвка 3: мини-демо — 4 вопроса квалификации, «проблема → решение», не больше 7 кликов, закрытие на следующий шаг","Ролёвка 4: клиент говорит «я подумаю» — доводишь до следующего шага по LAER","Разбор одной записи клиентской презентации из плейлиста по таблице стандарта демо","Практика CRM: ведёшь тестовую сделку по всей воронке от заявки до оплаты"],"result":"Почти готов работать с реальными лидами."}$sd$::jsonb, true)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, sort = EXCLUDED.sort, title = EXCLUDED.title, intro = EXCLUDED.intro, gate = EXCLUDED.gate, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000601$sd$, $sd$a0000000-0000-0000-0002-000000000006$sd$, 10, $sd$Чек-лист квалификации: 16 вопросов$sd$, $sd$20 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Какой вопрос критичен для конфигурации системы?","options":["Название компании","Van Sales или PreSale","Сколько лет на рынке","Есть ли сайт"],"correct":1},{"q":"ЛПР не может быть на презентации. Что делаем?","options":["Проводим без него","Переносим и собираем всех ЛПР","Отправляем КП","Закрываем сделку"],"correct":1},{"q":"Клиент избегает вопроса о бюджете. Что это значит?","options":["Бюджет большой","Скорее всего, бюджета нет — дожать или в прогрев","Нужно снизить цену","Позвонить позже"],"correct":1},{"q":"Горячий лид — это…","options":["Любой, кто оставил заявку","Бюджет утверждён, сроки до 3 мес, ЛПР будет на встрече","Клиент из A-сегмента","Кто открыл КП"],"correct":1},{"q":"Во сколько раз качественная квалификация повышает конверсию?","options":["В 1,5","В 3","В 10","Не влияет"],"correct":1}]$sd$::jsonb, $sd$<p>Квалификация — диагностика, а не допрос. Задача: понять, подходит ли клиент, готов ли он купить (бюджет, сроки, ЛПР) и как презентовать под его задачи. <b>Качественная квалификация повышает конверсию в 3 раза.</b></p>
<table class="tbl"><thead><tr><th>Блок</th><th>Вопросы</th><th>Как спросить</th></tr></thead><tbody>
<tr><td>1. База</td><td>Название компании; что реализуют</td><td>«Как правильно называется компания для документов?» «Какие категории товаров?»</td></tr>
<tr><td>2. Торговая команда</td><td>Сколько агентов; сколько экспедиторов; супервайзеры, мерчандайзеры</td><td>«Сколько агентов работает в поле?» «Кто занимается доставкой?»</td></tr>
<tr><td>3. Система продаж</td><td><b>Van Sales или PreSale</b> — критично для конфигурации</td><td>«Агенты продают и сразу привозят товар — или сначала заказ, потом доставка?»</td></tr>
<tr><td>4. Текущее ПО</td><td>Чем пользуются; какая 1С (конфигурация, платформа); что не устраивает</td><td>«1С у вас какая — УТ, КА? Платформа 8.3?» «С какими сложностями сталкиваетесь?»</td></tr>
<tr><td>5. ЛПР — критично</td><td>Кто принимает решение; будет ли на презентации — <b>дожать</b>; кто ещё влияет</td><td>«Важно, чтобы [имя ЛПР] присутствовал — сразу примем решение. Когда ему удобно?»</td></tr>
<tr><td>6. Сроки</td><td>Как скоро нужна; что триггер</td><td>«Что подтолкнуло к поиску: расширяетесь, проблемы с системой, сезон?»</td></tr>
<tr><td>7. Бюджет — важно</td><td>Какой бюджет; утверждён ли</td><td>«Решения на рынке от 100 тыс. до 2 млн — вы ближе к какому диапазону?»</td></tr>
</tbody></table>
<h4>Оценка лида</h4>
<div class="leads">
<div class="hot"><b>Горячий</b><span>Бюджет утверждён · сроки до 3 мес · ЛПР будет на встрече · размер подходит → презентация в ближайшие 2–3 дня</span></div>
<div class="warm"><b>Тёплый</b><span>Бюджет есть, но не утверждён · сроки 3–6 мес · ЛПР сложно вытащить → прогрев, встреча через 1–2 недели, материалы</span></div>
<div class="cold"><b>Холодный</b><span>Нет бюджета, «просто смотрим» · «когда-нибудь» · не подходит по размеру → nurturing, касание раз в месяц</span></div>
</div>
<div class="callout"><b>Без ЛПР на презентации конверсия падает в 10 раз.</b> Лучше перенести, но собрать всех ЛПР. <b>Бюджет не названный = бюджета нет.</b></div>$sd$, $sd$[{"t":"Чек-лист квалификации","u":"https://docs.google.com/document/d/1r7ehgyv9alKmYE8ZoPiaOKfkMFVlr8b8d2bXPISWlj4/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000602$sd$, $sd$a0000000-0000-0000-0002-000000000006$sd$, 20, $sd$Холодный звонок и закрытие на демо$sd$, $sd$20 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Пять блоков звонка по порядку:","options":["Прояснение → Вступление → Убеждение → Утепление → Завершение","Вступление → Утепление → Прояснение → Убеждение → Завершение","Визитка → Цена → Скидка → Договор → Счёт","Интрига → Демо → КП → Оплата → Отзыв"],"correct":1},{"q":"Что такое ПТС?","options":["Продукт, тариф, скидка","Почему тебе звоню","План, тезисы, скрипт","Продажа через сервис"],"correct":1},{"q":"Как предлагаем время демо в холодном звонке?","options":["«Когда вам удобно?»","«Сегодня в 15:00 или завтра в первой половине дня?»","«Напишите нам»","«Через неделю»"],"correct":1},{"q":"Что говорим в блоке «кстати»?","options":["Скидку","Партнёрство с 2ГИС / гарантию","Цену","Имя директора"],"correct":1},{"q":"Техника «Программирование» — это…","options":["Настройка CRM","Согласовать с клиентом сценарий разговора до вопросов","Написать код","Запланировать звонок"],"correct":1}]$sd$::jsonb, $sd$<h4>Структура любого звонка — 5 блоков</h4>
<div class="flow"><span class="node">Вступление</span><span class="arr">→</span><span class="node">Утепление</span><span class="arr">→</span><span class="node">Прояснение</span><span class="arr">→</span><span class="node">Убеждение</span><span class="arr">→</span><span class="node">Завершение</span></div>
<table class="tbl"><thead><tr><th>Блок</th><th>Элементы</th><th>Как звучит</th></tr></thead><tbody>
<tr><td><b>Вступление</b></td><td>Телефонная визитка · интрига · вовлекающий вопрос</td><td>«Добрый день, Иван Иванович? Это [Имя], компания Зейд Плюс. Есть одно решение, которое сейчас активно внедряют дистрибьюторы — удобно пару минут?»</td></tr>
<tr><td><b>Утепление</b></td><td>ПТС (почему тебе звоню) · высшая выгода · вопрос-предвосхищение</td><td>«Вы работаете в дистрибуции, а мы автоматизируем как раз такие компании. Работаем с Grizzly, недавно подключился крупный FMCG-производитель. Торговые вносят заявки с телефона, логисты получают маршруты, руководитель видит всё в реальном времени. Ошибки падают до 5 %, логистика дешевеет на 20 %. Я правильно понимаю, что у вас уже что-то используется?»</td></tr>
<tr><td><b>Прояснение</b></td><td>Программирование · продающие вопросы · квалификация</td><td>«Тогда пару вопросов — и покажу, чем усиливаем существующие системы. 1. Сколько активных пользователей — торговые и логисты? 2. Где ведутся заявки — Excel, 1С, CRM? 3. Бывало, что заявки теряются или логистика плавает?»</td></tr>
<tr><td><b>Убеждение</b></td><td>Сотрудничество · КЭВ · здесь и сейчас</td><td>«Именно с такими кейсами мы работаем. Покажу коротко на Zoom: как торговые оформляют заказы, как система маршрутизирует доставку, как аналитика считает KPI. 20 минут. Когда удобно: сегодня в 15:00 или завтра в первой половине дня?»</td></tr>
<tr><td><b>Завершение</b></td><td>Призыв · возражения · резюме · «кстати»</td><td>«Фиксирую Zoom на [время], пришлю ссылку за час. Кстати, мы стали официальными партнёрами 2ГИС — прямо в систему загружается база торговых точек. В любом случае есть гарантия: не бросаем после внедрения.»</td></tr>
</tbody></table>
<h4>Техника «Программирование»</h4>
<p>«Чтобы подобрать лучший для вас вариант, позвольте несколько вопросов уточню, потом расскажу, какие варианты возможны. Если всё устроит — согласуем следующие шаги, хорошо?» Клиент соглашается на сценарий — и не сопротивляется вопросам.</p>
<h4>Чек-лист исходящего звонка — что оценивает РОП</h4>
<ul>
<li><b>Подготовка:</b> цели MAX / MIN, сегмент клиента, тезисы, возможные боли</li>
<li><b>Открытие:</b> корпоративное представление, выявить ЛПР, узнать имя, упомянуть опыт с аналогичными дистрибьюторами, без зависаний</li>
<li><b>Прояснение:</b> минимум 3 вовлекающих вопроса, программирование, активное слушание (эхо, парафраз), обращение по имени</li>
<li><b>Презентация:</b> на целевое действие; цифры −40 % / контроль агентов в реальном времени; от $10 за пользователя, внедрение от $1 000</li>
<li><b>Возражения:</b> не спорить, конкретизировать, согласиться с чем можно, аргументы, призыв к ЦД</li>
<li><b>Завершение:</b> сигналы к ЦД, пробный доступ на 14 дней или демо, резюме, позитивное прощание</li>
<li><b>Голос:</b> громкость, паузы, интонация, короткие предложения, без слов-паразитов</li>
</ul>$sd$, $sd$[{"t":"Скрипт холодного звонка","u":"https://docs.google.com/document/d/1uSQYvL2BizEaC0VTIsmKakc1hLIUZqeo-PDbz-u6sEo/edit"},{"t":"Закрытие на демо","u":"https://docs.google.com/document/d/1x7fqSvlK4CxR63PhzQczUonUB9uvRtnVKKZy5jiB6-I/edit"},{"t":"Чек-лист исходящего звонка","u":"https://docs.google.com/spreadsheets/d/1sUaQzOQyEmV-u8lSdiskkw-FYuBzfJoZfbuUbKNvWpc/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000603$sd$, $sd$a0000000-0000-0000-0002-000000000006$sd$, 30, $sd$Входящий звонок и закрытие на продукт$sd$, $sd$15 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Клиент говорит «у нас уже что-то есть» на входящем. Ответ по скрипту:","options":["«Тогда до свидания»","«Часто внедряем параллельно — клиент сам сравнивает и решает»","«Ваша система плохая»","«Дадим скидку»"],"correct":1},{"q":"Какой ROI называем на входящем звонке?","options":["1 год","3–4 месяца","2 года","Не называем"],"correct":1},{"q":"Закрывающий вопрос после демо:","options":["«Будете покупать?»","«Сразу запускать проект или сначала пилот?»","«Подумаете?»","«Какая у вас цена?»"],"correct":1},{"q":"Пилот — это…","options":["Бесплатный год","5–7 пользователей в боевом режиме","Демо-стенд","Скидка 50 %"],"correct":1}]$sd$::jsonb, $sd$<h4>Входящий — закрытие на демо</h4>
<p>«Добрый день, Иван Иванович? Это [Имя], компания Зейд Плюс, вижу, вы интересовались нашим решением для автоматизации дистрибуции — удобно пару минут? Как раз вовремя — сейчас внедряем обновление у одной FMCG-компании, цифры интересные.»</p>
<p>Коротко: заявки в 2 клика с телефона, контроль торговых офлайн, логистика с отслеживанием, аналитика в реальном времени. −40 % время обработки, −20 % логистика, ROI обычно 3–4 месяца. «Понимаю, у вас, скорее всего, уже что-то есть. Часто внедряем параллельно — клиент сам сравнивает.» → «Предлагаю не тратить время на чтение, а сразу покажу в Zoom: 20 минут, живые примеры, кейсы Nestle и Grizzly, расчёты. Сегодня в 16:00 или завтра утром?» → «Кстати, есть модуль геймификации для агентов — +18 % к продажам, тоже покажу.»</p>
<h4>Закрытие после демо — переход к сделке</h4>
<table class="tbl"><thead><tr><th>Блок</th><th>Как звучит</th></tr></thead><tbody>
<tr><td>Вступление</td><td>«Хотел обсудить вариант запуска системы под вашу команду. Удобно 2–3 минуты?»</td></tr>
<tr><td>Утепление</td><td>«На демо говорили, что теряются заявки и бывают задержки. У Grizzly была похожая ситуация. Система понравилась — нужно только согласовать запуск, верно?»</td></tr>
<tr><td>Прояснение</td><td>«Сколько пользователей подключаем на первом этапе? Есть ли ограничения по бюджету или процессу согласования?»</td></tr>
<tr><td>Убеждение</td><td>«По тому, что обсудили: 15 пользователей, интеграция с 1С, старт в течение месяца. Базовая лицензия, внедрение под ключ, запуск 2 недели с момента ТЗ, поддержка 24/7 и персональный менеджер. Для старта можно пилот на 5–7 пользователях.»</td></tr>
<tr><td>Завершение</td><td>«Какой формат ближе: сразу запускать или сначала пилот?» → «Направлю соглашение и анкету по старту. Кстати, планируете расширение команды или смену ERP? Учтём сейчас.»</td></tr>
</tbody></table>
<div class="callout">Выбор без выбора: «сразу проект или сначала пилот?» — оба ответа ведут к сделке. Бонус фиксируется на 2 дня, если клиент сомневается.</div>$sd$, $sd$[{"t":"Скрипт входящего","u":"https://docs.google.com/document/d/1jj3qYrL_0L-yiEdtYRQd_3bZ0QfBec24VU5H7cSNMUk/edit"},{"t":"Закрытие на продукт","u":"https://docs.google.com/document/d/1-B6ICDUeSJqZdnJRqlyLhi_Y_IMDGpugzumFRkZ0-AI/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000604$sd$, $sd$a0000000-0000-0000-0002-000000000006$sd$, 40, $sd$Стандарт демо-встречи$sd$, $sd$25 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Сколько времени на квалификацию в начале демо?","options":["1 минута","5 минут","15 минут","30 минут"],"correct":1},{"q":"Правило кликов в демо:","options":["Не больше 3","Не больше 7","Не больше 20","Без ограничений"],"correct":1},{"q":"Соотношение «говорит менеджер / клиент»:","options":["70 / 30","50 / 50","30 / 70","90 / 10"],"correct":2},{"q":"За сколько после встречи уходит письмо-резюме?","options":["В течение 60 минут","На следующий день","Через неделю","Не обязательно"],"correct":0},{"q":"Клиент: «Покажите уже программу». Правильно:","options":["Показать всё","Два вопроса — сколько людей и где потери — и сразу этот блок","Отказать","Перенести встречу"],"correct":1}]$sd$::jsonb, $sd$<h4>Этап 0 — подготовка</h4>
<ul><li>Техника: интернет, гарнитура, демо-среда, лишние вкладки закрыты, тестовый звонок себе</li><li>Клиент за 15–30 минут: сайт, CRM-профиль, специфика, 3–5 гипотез о болях</li><li>Материалы: шаблон КП, калькулятор ROI, кейсы из отрасли, ответы на возражения</li></ul>
<h4>Этап 1 — начало, 0–5 минут</h4>
<p>Приветствие → проверка связи и правила («буду останавливаться для вопросов, можете перебивать») → цель и время («за 30 минут покажу, как решаем [боль], в конце — следующие шаги, устраивает?») → переход к вопросам.</p>
<h4>Этап 2 — квалификация, 5 минут: только 4 вещи</h4>
<ol><li>Сколько пользователей — торгпреды / экспедиторы / руководители</li><li>Главная боль — 1–2 пункта максимум</li><li>Что уже используют</li><li>Кто принимает решение и когда</li></ol>
<p><b>«Покажите уже программу»</b> — клиент проверяет, продавец вы или помощник: «Конечно. Чтобы не показывать всё подряд, два вопроса: сколько людей будет в системе и где больше всего потерь — заявки, доставка или контроль торговых? И сразу показываю этот блок.»</p>
<h4>Этап 3 — презентация, 15–30 минут</h4>
<ul>
<li><b>Проблема → решение:</b> «Вы упомянули [X]. Вот как это решается: [функционал]».</li>
<li>3–5 преимуществ по важности для клиента: главная боль → вторая → уникальное преимущество → лёгкость внедрения → поддержка.</li>
<li>Техника <b>«Что вы видите — что это значит — почему это важно для вас»</b>.</li>
<li>Правило <b>«не больше 7 кликов»</b>: сценарий готов заранее, только важное.</li>
<li>Проверка понимания каждые 5–7 минут: «Какие вопросы по этому блоку?»</li>
</ul>
<h4>Этап 4 — возражения, 5–10 минут: LAER</h4>
<p>«Дорого» → «Давайте посчитаем: у вас 15 торговых, если каждый увеличит эффективность на 15 % — это [деньги]. Окупаемость 2–3 месяца. Показать на ваших цифрах?»</p>
<h4>Этап 5 — закрытие, 5–10 минут</h4>
<p>Резюме («обсудили [боль 1] → [решение 1]…») → проверка готовности («по 10-балльной шкале, насколько видите ценность?») → следующий шаг: договор с тестовым периодом / демо для руководителя / персональное КП с ROI → точная дата → подтверждение письменно.</p>
<h4>Этап 6 — после встречи, до 60 минут</h4>
<ul><li>Сразу: CRM — контакт, статус, следующие шаги</li><li>В течение 60 минут: письмо-резюме, материалы, встреча в календаре</li></ul>
<h4>Метрики хорошей встречи</h4>
<div class="kpis"><div><b>80 %+</b><span>встреч заканчиваются назначенным следующим шагом</span></div><div><b>&lt; 60 мин</b><span>до follow-up</span></div><div><b>30 / 70</b><span>говорит менеджер / клиент</span></div><div><b>15+</b><span>вопросов за встречу</span></div></div>
<h4>Никогда</h4>
<p>Говорить больше клиента · показывать всё подряд · перебивать · оставлять следующий шаг размытым («свяжемся как-нибудь») · забывать follow-up в день встречи · обещать невыполнимое · игнорировать «мне надо подумать» (= есть конкретное сомнение).</p>$sd$, $sd$[{"t":"Стандарт демо-встречи","u":"https://docs.google.com/document/d/1Z7sz8Mc9q_DAdYB1IqKs9d2CrsC3kej8OxacbiKcWJM/edit"},{"t":"Чек-лист презентации","u":"https://docs.google.com/spreadsheets/d/1OYSHqVqh2OFjxGoy35NbKkgtlvtwlbUFNoXi2zeZZno/edit"}]$sd$::jsonb, NULL, NULL, true)
