INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000605$sd$, $sd$a0000000-0000-0000-0002-000000000006$sd$, 50, $sd$Смотрим, как это делают: видео презентаций$sd$, $sd$90 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Какое видео из плейлиста обязательно к просмотру целиком?","options":["Мастер-класс","Первичная презентация Sales Doctor","Презентация Даурен","Любое"],"correct":1},{"q":"Что заполняешь во время просмотра клиентской встречи?","options":["Отзыв на YouTube","Таблицу разбора по стандарту демо","КП","Карточку в CRM"],"correct":1},{"q":"Сколько разборов встреч нужно для перехода на грейд «Менеджер по продажам»?","options":["3","5","10","20"],"correct":2},{"q":"Мастер-класс — это формат КЭВ для…","options":["A-сегмента","Группы / C-сегмента","Только партнёров","Сотрудников"],"correct":1}]$sd$::jsonb, $sd$<p>Плейлист «Презентации» канала Sales Doctor — записи реальных демо и мастер-класса. Смотри не как зритель, а с чек-листом стандарта демо в руках.</p>
<h4>Обязательно — первичная презентация</h4>
<div class="vids">
<a class="vid" href="https://www.youtube.com/watch?v=D5lsMAklAtI&list=PLh4oaxt-37pxM6bRL_paHB9TnvNq5Zzhy" target="_blank" rel="noopener"><span class="play">▶</span><span class="vt"><b>Sales Doctor — первичная презентация</b><span>Эталонный прогон продукта: модули для ТП, логистов, руководителя. Смотреть целиком, с паузами — запиши последовательность экранов, чтобы повторить на своём мини-демо.</span></span><span class="dur">40:14</span></a>
</div>
<h4>По выбору — минимум одна встреча с клиентом</h4>
<div class="vids">
<a class="vid" href="https://www.youtube.com/watch?v=aOPqk-VbsbM&list=PLh4oaxt-37pxM6bRL_paHB9TnvNq5Zzhy" target="_blank" rel="noopener"><span class="play">▶</span><span class="vt"><b>Презентация клиенту Багдат</b><span>Короткая встреча — хороший пример темпа и структуры на 30 минут.</span></span><span class="dur">30:00</span></a>
<a class="vid" href="https://www.youtube.com/watch?v=FN9-5Wu_5Y4&list=PLh4oaxt-37pxM6bRL_paHB9TnvNq5Zzhy" target="_blank" rel="noopener"><span class="play">▶</span><span class="vt"><b>Презентация ИП Аскат</b><span>Встреча с небольшим дистрибьютором — C/B-сегмент.</span></span><span class="dur">1:04:01</span></a>
<a class="vid" href="https://www.youtube.com/watch?v=lxlnJav7RPc&list=PLh4oaxt-37pxM6bRL_paHB9TnvNq5Zzhy" target="_blank" rel="noopener"><span class="play">▶</span><span class="vt"><b>Презентация Даурен</b><span>Длинная встреча — смотри, где клиент задаёт вопросы и как менеджер возвращает управление.</span></span><span class="dur">1:26:40</span></a>
<a class="vid" href="https://www.youtube.com/watch?v=j_ZaF7fvx5w&list=PLh4oaxt-37pxM6bRL_paHB9TnvNq5Zzhy" target="_blank" rel="noopener"><span class="play">▶</span><span class="vt"><b>Мастер-класс Мирзахит</b><span>Формат КЭВ для группы — как проходит вебинар / мастер-класс для C-сегмента.</span></span><span class="dur">54:45</span></a>
</div>
<h4>Ещё четыре записи — из Академии Sales Doctor</h4>
<div class="vids">
<a class="vid" href="https://www.loom.com/share/c3c4955a1e0d4141af399290deaa7820" target="_blank" rel="noopener"><span class="play">▶</span><span class="vt"><b>Демо для дистрибьютора #1 · Loom</b><span>Запись реальной встречи: как менеджер презентует и отвечает на вопросы.</span></span><span class="dur">Loom</span></a>
<a class="vid" href="https://www.loom.com/share/97cf6768f3734e87902d89dbd090945c" target="_blank" rel="noopener"><span class="play">▶</span><span class="vt"><b>Демо для дистрибьютора #2 · Loom</b><span>Сравни подход с предыдущим видео.</span></span><span class="dur">Loom</span></a>
<a class="vid" href="https://www.loom.com/share/d525967939f64d9fbbde5aabbb6d474d" target="_blank" rel="noopener"><span class="play">▶</span><span class="vt"><b>Демо для дистрибьютора #3 · Loom</b><span>Обрати внимание на работу с возражениями.</span></span><span class="dur">Loom</span></a>
<a class="vid" href="https://drive.google.com/file/d/15-ULOvWdZWiGwg1GMub68o1FlyGjbUFt/view" target="_blank" rel="noopener"><span class="play">▶</span><span class="vt"><b>Демо из архива · Drive</b><span>Видеозапись демо-встречи из архива команды.</span></span><span class="dur">Drive</span></a>
</div>
<h4>Задание: разбор по стандарту</h4>
<p>Пока смотришь клиентскую встречу, заполни таблицу — она же пойдёт наставнику на зачёте.</p>
<table class="tbl"><thead><tr><th>Что ищем</th><th>Норма из стандарта</th><th>Как было в видео</th></tr></thead><tbody>
<tr><td>Начало</td><td>Приветствие, правила, цель и время — до 5 мин</td><td>&nbsp;</td></tr>
<tr><td>Квалификация</td><td>4 вещи за 5 минут: пользователи, боль, что используют, ЛПР</td><td>&nbsp;</td></tr>
<tr><td>Презентация</td><td>«Проблема → решение», ≤ 7 кликов, проверка понимания каждые 5–7 мин</td><td>&nbsp;</td></tr>
<tr><td>Соотношение речи</td><td>Менеджер 30 % / клиент 70 %</td><td>&nbsp;</td></tr>
<tr><td>Возражения</td><td>LAER, «дорого» — через расчёт</td><td>&nbsp;</td></tr>
<tr><td>Закрытие</td><td>Резюме, шкала 1–10, следующий шаг с датой</td><td>&nbsp;</td></tr>
</tbody></table>
<div class="callout">Из условий перехода на грейд «Менеджер по продажам»: <b>просмотр 10 разборов встреч</b>. Плейлист и записи Академии — первые девять. Записи новых встреч появляются в папке «Презентации» на Drive и на канале.</div>$sd$, $sd$[{"t":"Плейлист «Презентации» · YouTube","u":"https://youtube.com/playlist?list=PLh4oaxt-37pxM6bRL_paHB9TnvNq5Zzhy"},{"t":"Стандарт демо-встречи","u":"https://docs.google.com/document/d/1Z7sz8Mc9q_DAdYB1IqKs9d2CrsC3kej8OxacbiKcWJM/edit"}]$sd$::jsonb, NULL, NULL, true)
