INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000606$sd$, $sd$a0000000-0000-0000-0002-000000000006$sd$, 60, $sd$Доверие и запись встреч$sd$, $sd$15 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Четыре компонента доверия:","options":["Цена, скорость, качество, сервис","Экспертность, эмпатия, честность, что-то общее","Кейсы, отзывы, скидки, гарантии","Звонок, письмо, встреча, договор"],"correct":1},{"q":"Чем записываем демо экрана?","options":["Zoom","Bandicam","dapmeet","Loom"],"correct":1},{"q":"В какой срок отправляем запись клиенту?","options":["В течение 1–2 часов","На следующей неделе","Через 3 дня","По запросу"],"correct":0},{"q":"С какими правами делимся ссылкой на запись?","options":["Редактор","Читатель","Владелец","Комментатор"],"correct":1},{"q":"Пример «мини-недостатка» для честности:","options":["«У нас нет поддержки»","«Мы не внедряем за 1 день — зато делаем правильно»","«Мы дороже всех»","«Приложение иногда падает»"],"correct":1}]$sd$::jsonb, $sd$<h4>Четыре компонента доверия</h4>
<ul>
<li><b>Экспертность:</b> 3 упакованных кейса B-сегмента «до / после», отзывы со скриншотами, цифры в презентации (дней запуск, пользователей, эффект), очередь клиентов и бренды — Nestle, Grizzly.</li>
<li><b>Эмпатия:</b> проговаривать боли языком клиента — «агент не донёс заявку, магазин остался без поставки», «водитель потерял бумажку — нет доставки»; вопросы вглубь: «как сейчас фиксируются заявки? кто отслеживает доставку?»</li>
<li><b>Честность:</b> ограничения и риски вслух — «старт возможен через 10 дней»; мини-недостаток — «мы не внедряем за 1 день, зато делаем правильно»; гарантия — доп. месяц поддержки при задержке.</li>
<li><b>Что-то общее:</b> «мы автоматизировали 15+ дистрибьюторов», «работаем с компаниями из вашей сферы — торговые, дистрибьюторы, FMCG», «многие наши клиенты сталкивались с этим».</li>
</ul>
<h4>Запись презентаций — обязательна</h4>
<p>Клиенты, получившие запись, закрываются на 35 % быстрее, конверсия выше на 28 %. Видео работает как виртуальный менеджер 24/7 и доходит до ЛПР, которого не было на встрече.</p>
<ol>
<li><b>До встречи:</b> Bandicam открыт за 5 минут, запись экрана, микрофон включён, 1080p, MP4, тестовая запись 10 секунд.</li>
<li><b>В начале:</b> «[Имя], я записываю встречу, чтобы отправить вам видео — пересмотрите и покажете коллегам. Удобно?»</li>
<li><b>dapmeet</b> настроен один раз — транскрибирует все встречи в Google Meet автоматически. Bandicam — видео демо, dapmeet — транскрипт разговора. Часто оба на одной встрече.</li>
<li><b>После:</b> проверить первые 2–3 минуты записи; переименовать <code>Компания_дата_презентация.mp4</code>; загрузить в Google Drive → папка «Презентации»; доступ по ссылке, права «Читатель»; проверить ссылку в инкогнито.</li>
<li><b>Отправить в течение 1–2 часов</b> письмом по шаблону: благодарность, ссылка, 3 ключевых момента, следующие шаги с датой.</li>
<li><b>Через 24 часа</b> — follow-up: «Посмотрели? Есть вопросы?»</li>
</ol>$sd$, $sd$[{"t":"Усилители доверия","u":"https://docs.google.com/document/d/1irHvZbYU3NdwE4FpZLyNxkWZf3PjwaK3Y7JPk1TALaw/edit"},{"t":"Инструкция записи встреч","u":"https://docs.google.com/document/d/1DMSZVKs7q2KOGD5tnn02RI4r5IybfzHi9cfSThFaH6o/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;
